#头文件 #include &#34;co/def.h&#34; #整型别名 typedef int8_t int8; typedef int16_t int16; typedef int32_t int32; typedef int64_t int64; typedef uint8_t uint8; typedef uint16_t uint16; typedef uint32_t uint32; typedef uint64_t uint64; 定义在全局命名空间。 #整型极值常量 namespace co { constexpr uint8 max_uint8 = (uint8) ~((uint8) 0); constexpr uint16 max_uint16 = (uint16) ~((uint16)0); constexpr uint32 max_uint32 = (uint32) ~((uint32)0); constexpr uint64 max_uint64 = (uint64) ~((uint64)0); constexpr int8 max_int8 = (int8) (max_uint8 &gt;&gt; 1); constexpr int16 max_int16 = (int16) (max_uint16 &gt;&gt; 1); constexpr int32 max_int32 = (int32) (max_uint32 &gt;&gt; 1); constexpr int64 max_int64 = (int64) (max_uint64 &gt;&gt; 1); constexpr int8 min_int8 = (int8) ~max_int8; constexpr int16 min_int16 = (int16) ~max_int16; constexpr int32 min_int32 = (int32) ~max_int32; constexpr int64 min_int64 = (int64) ~max_int64; } // co 定义在 co 命名空间，均为 constexpr。 示例:
#include &#34;co/def.h&#34; #include &#34;co/print.h&#34; int main() { co::println(&#34;max_uint32 = &#34;, co::max_uint32); co::println(&#34;max_int32 = &#34;, co::max_int32); co::println(&#34;min_int32 = &#34;, co::min_int32); return 0; } #缓存行大小 提供编译期常量 co::cache_line_size，常用于内存对齐、避免伪共享。各架构取值如下：
架构 co::cache_line_size S390X 256 PowerPC64 128 ARM64 128 其它（x86、x64 等） 64 co::cache_line_size 可能大于实际缓存行大小，对齐或填充时会多占少量内存，通常影响较小。 示例:
// 分配缓存行对齐的内存 co::alloc(n, co::cache_line_size); #宏 #架构 #if SIZE_MAX == UINT64_MAX #define __arch64 1 #elif SIZE_MAX == UINT32_MAX #define __arch32 1 #else #error &#34;platform not supported&#34; #endif 64 位平台定义 __arch64 宏，值为 1； 32 位平台定义 __arch32 宏，值为 1； #缓存行对齐 #ifndef __cacheline_aligned #define __cacheline_aligned alignas(co::cache_line_size) #endif __cacheline_aligned 宏让变量或结构体按缓存行对齐。 示例：
struct __cacheline_aligned Foo { int x; }; #线程局部存储 #ifdef _MSC_VER #ifndef __thread #define __thread __declspec(thread) #endif #endif __thread 用于定义线程局部变量； gcc/clang 已内置 __thread，Windows 上(使用 MSVC)将其定义为 __declspec(thread)。 示例：
__thread int g_v; __thread void* g_p; #__unlikely 提示编译器条件为假概率更高。 旧版本中名为 unlikey，为避免与 C++20 [[unlikely]] 冲突，改为 __unlikely。 示例：
fs::file f(&#34;xx.log&#34;, &#39;r&#39;); if (__unlikely(!f)) co::println(&#34;open file failed&#34;);

include: co/co.h.
#co::chan template&lt;typename T&gt; class chan; co::chan 是一个模板类，它类似于 golang 中的 channel，用于在协程之间传递数据。
从 v3.0.1 开始，co::chan 可在协程或非协程中使用，且可存储 std::string 等非 POD 类型的值。 #constructor 1. explicit chan(uint32 cap=1, uint32 ms=(uint32)-1); 2. chan(chan&amp;&amp; c); 3. chan(const chan&amp; c); 1, 参数 cap 是内部队列的最大容量，默认是 1，参数 ms 是读写操作的超时时间，单位为毫秒，默认为 -1，永不超时。 2, 移动构造函数。 3, 拷贝构造函数，仅将内部引用计数加 1。 #close void close() const; 关闭 channel，关闭后 channel 不可写，但可读。 #done bool done() const; 判断读、写操作是否成功完成。 #operator bool explicit operator bool() const; 若 channel 为关闭状态，返回 false，否则返回 true。 #operator&laquo; chan&amp; operator&lt;&lt;(const T&amp; x) const; chan&amp; operator&lt;&lt;(T&amp;&amp; x) const; 写入元素 x。 此方法会阻塞，直到写入操作完成或超时。可以调用 done() 方法判断写操作是否成功完成。 若 channel 已关闭，写操作会失败，此方法立即返回。 #operator&raquo; chan&amp; operator&gt;&gt;(T&amp; x) const; 读取元素。 此方法会阻塞，直到读取操作完成或超时。可以调用 done() 方法判断读操作是否成功完成。 若 channel 已关闭且 channel 中无元素可读时，读操作会失败，此方法立即返回。 #代码示例 #include &#34;co/co.h&#34; #include &#34;co/cout.h&#34; void f() { co::chan&lt;int&gt; ch; go([ch]() { ch &lt;&lt; 7; }); int v = 0; ch &gt;&gt; v; co::print(&#34;v: &#34;, v); } void g() { co::chan&lt;int&gt; ch(32, 500); go([ch]() { ch &lt;&lt; 7; if (!ch.done()) co::print(&#34;write to channel timeout..&#34;); }); int v = 0; ch &gt;&gt; v; if (ch.done()) co::print(&#34;v: &#34;, v); } int main(int argc, char** argv) { flag::parse(argc, argv); f(); g(); return 0; }

include: co/co.h.
#co::event co::event 是协程间的一种同步机制，它与线程中的 co::sync_event 类似。
从 v2.0.1 版本开始，co::event 可以在协程与非协程中使用。 #constructor 1. explicit event(bool manual_reset=false, bool signaled=false); 2. event(event&amp;&amp; e); 3. event(const event&amp; e); 1, 与线程中的 co::sync_event 类似。 2, 移动构造函数。 3, 拷贝构造函数，仅将内部引用计数加 1。 #reset void reset() const; 将事件重置为未同步状态。 #signal void signal() const; 产生同步信号，将事件设置成同步状态。 所有 waiting 状态的协程或线程会被唤醒。若当前并没有 waiting 状态的协程或线程，则下一个调用 wait() 方法的协程或线程会立即返回。 #wait 1. void wait() const; 2. bool wait(uint32 ms) const; 1, 等待直到事件变成同步状态。 2, 等待直到事件变成同步状态或超时。参数 ms 指定超时时间，单位为毫秒。若事件变成同步状态，返回 true，否则返回 false。 当构造函数中 manual_reset 为 false 时，wait() 结束时会自动将事件设置成未同步状态。 #代码示例 #include &#34;co/co.h&#34; int main(int argc, char** argv) { flag::parse(argc, argv); co::event ev; // capture by value, // as data on stack may be overwritten by other coroutines. go([ev](){ ev.signal(); }); ev.wait(100); // wait for 100 ms return 0; }

include: co/co.h.
#co::wait_group co::wait_group 类似于 golang 中的 sync.WaitGroup，可用于等待协程或线程的退出。
#constructor 1. explicit wait_group(uint32 n); 2. wait_group(); 3. wait_group(wait_group&amp;&amp; wg); 4. wait_group(const wait_group&amp; wg); 1, 将内部计数器初始化为 n。 2, 默认构造函数，将内部计数器初始化为 0。 3, 移动构造函数。 4, 拷贝构造函数，仅将内部引用计数加 1。 #add void add(uint32 n=1) const; 将内部计数器加 n，n 默认为 1。 #done void done() const; 将内部计数器减 1。 #wait void wait() const; 等待直到内部计数器的值变为 0。 #代码示例 #include &#34;co/co.h&#34; #include &#34;co/cout.h&#34; DEF_uint32(n, 8, &#34;coroutine number&#34;); int main(int argc, char** argv) { flag::parse(argc, argv); co::wait_group wg; wg.add(FLG_n); for (uint32 i = 0; i &lt; FLG_n; ++i) { go([wg]() { co::print(&#34;sched: &#34;, co::sched_id(), &#34; co: &#34;, co::coroutine_id()); wg.done(); }); } wg.wait(); return 0; }
